import{_ as s,o as i,c as a,a2 as t}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"docs/guide/getting-started.md","filePath":"guide/getting-started.md"}'),n={name:"docs/guide/getting-started.md"};function l(o,e,h,r,p,d){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Kittyscape selects a local background image from your shell’s directory. The active pane in the selected tab controls the image for its <strong>OS window</strong>, meaning the outer window managed by your desktop.</p><div class="warning custom-block"><p class="custom-block-title">Experimental local build</p><p>Qualification is still in progress. Read the <a href="./../reference/compatibility.html">compatibility matrix</a> and <a href="./uninstall.html">removal instructions</a> before changing a kitty configuration. Use a disposable kitty configuration while evaluating this build.</p></div><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>You need kitty, a shell with working kitty directory reports, and local PNG images you can read. The extension uses kitty’s embedded Python. Node.js is only needed to work on this documentation site.</p><p>Check the exact versions and configuration profiles in <a href="./../reference/compatibility.html">compatibility</a>. An installed shell executable alone does not establish working directory reports.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Run <code>kitty +launch ./setup.py install</code> from the extracted bundle. It writes the small kitty loader, creates <code>~/.config/kittyscape/kittyscape.json</code> when absent, and opens a fresh configured kitty window. See <a href="./installation.html">installation</a> for a custom location, preview mode, and removal.</p><h2 id="give-two-directories-a-background" tabindex="-1">Give two directories a background <a class="header-anchor" href="#give-two-directories-a-background" aria-label="Permalink to &quot;Give two directories a background&quot;">​</a></h2><p>Edit <code>~/.config/kittyscape/kittyscape.json</code>. The following example gives a project one image and a nested directory another. Replace the directory paths and provide the two PNG files.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;rules&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;directory&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/Projects/Little Garden&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;image&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;images/garden.png&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;directory&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/Projects/Little Garden/seedlings&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;image&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;images/seedlings.png&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Image paths here are relative to the directory containing <code>kittyscape.json</code>. They do not change meaning when the shell moves. See <a href="./configuration.html">configuration</a> for symlinks, nested rules, and fallback images.</p><h2 id="check-the-result" tabindex="-1">Check the result <a class="header-anchor" href="#check-the-result" aria-label="Permalink to &quot;Check the result&quot;">​</a></h2><p>In an isolated interactive shell, enter each directory. These quoted <code>cd</code> commands work in Bash, Zsh, and Fish:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/&quot;Projects/Little Garden&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> seedlings</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~</span></span></code></pre></div><p>The expected sequence is garden image, seedlings image, then the captured original background. A terminal that began with no image returns to no image. Restoration depends on the <a href="./../reference/compatibility.html">qualified baseline profile</a>.</p><p>Switch between two panes with different directories, then between tabs. The selected tab’s active pane decides its OS window’s background. Check that two OS windows keep independent images.</p><p>If any check fails, use <a href="./troubleshooting.html">troubleshooting</a>, then <a href="./uninstall.html">restore and remove</a>.</p>`,18)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
